This Terraform configuration creates an AWS Lightsail instance using the official WordPress blueprint. It also creates an SSH key pair, attaches a static public IP address, and opens common WordPress ports: SSH, HTTP, and HTTPS.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail WordPress instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone for the Lightsail instance."
  type        = string
  default     = "us-east-1a"
}

variable "instance_name" {
  description = "Name of the Lightsail WordPress instance."
  type        = string
  default     = "wordpress-lightsail"
}

